SELECT T1."U_BelowCst", T0."DocNum" as "GRPO No.", T0."BPLName", T0."CardCode",T0."CardName",T1."ItemCode",T1."Dscription", T1."CodeBars",T1."UomCode", T1."Price", T1."U_RetailPrice", T1."U_suppprice" FROM OPDN T0 INNER JOIN PDN1 T1 ON T0."DocEntry" = T1."DocEntry"  WHERE T1."U_BelowCst" ='Yes' and  T0."CreateDate"=CURRENT_DATE  and  LEFT(LPAD(T0."CreateTS",6,'0'),4)>=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,-3600), 'HH24MI')
